/** 
 * Displays the selected function on the state view.
 */
@Override public void initialize(){
  csp=null;
switch (simPaneCtrl.getParamValueIndex(PARAM_MAP)) {
case 0:    initMapOfAustraliaCsp();
  break;
case 1:initMapOfAustraliaCsp();
csp.setDomain(MapCSP.NSW,new Domain<>(MapCSP.BLUE));
break;
case 2:initMapOfAustraliaCsp();
csp.setDomain(MapCSP.WA,new Domain<>(MapCSP.RED));
break;
case 3:initTreeCsp();
break;
}
switch (simPaneCtrl.getParamValueIndex(PARAM_STRATEGY)) {
case 0:strategy=new FlexibleBacktrackingSolver<>();
break;
case 1:strategy=new FlexibleBacktrackingSolver<Variable,String>().set(CspHeuristics.deg());
break;
case 2:strategy=new FlexibleBacktrackingSolver<Variable,String>().set(new ForwardCheckingStrategy<>());
break;
case 3:strategy=new FlexibleBacktrackingSolver<Variable,String>().set(CspHeuristics.mrvDeg()).set(new ForwardCheckingStrategy<>());
break;
case 4:strategy=new FlexibleBacktrackingSolver<Variable,String>().set(CspHeuristics.lcv()).set(new ForwardCheckingStrategy<>());
break;
case 5:strategy=new FlexibleBacktrackingSolver<Variable,String>().set(new AC3Strategy<>());
break;
case 6:strategy=new FlexibleBacktrackingSolver<Variable,String>().setAll();
break;
case 7:strategy=new MinConflictsSolver<>(50);
break;
case 8:strategy=new TreeCspSolver<>();
break;
case 9:strategy=new TreeCspSolver<Variable,String>().useRandom(true);
break;
}
strategy.addCspListener((csp1,assignment) -> {
stepCounter++;
updateStateView(csp1,assignment);
}
);
stateViewCtrl.initialize(csp);
}
